 static String unique(String seed,Set<String> names){String value=seed;int n=2;while(!names.add(value))value=seed+"_"+(n++);return value;}
 static String bool(boolean value){return value?"true":"false";}
 static String number(double value){if(value==0)return "Value.number(0.0)";if(Math.abs(value)<=9000000000d){long power=1;for(int digits=0;digits<=6;digits++,power*=10){double scaled=value*power;if(scaled!=Math.floor(scaled))continue;String text=Long.toString((long)Math.abs(scaled));while(text.length()<digits+1)text="0"+text;if(digits>0)text=text.substring(0,text.length()-digits)+"."+text.substring(text.length()-digits);if(value<0)text="-"+text;if(Double.parseDouble(text)==value)return "Value.number("+text+(digits==0?".0":"")+")";}}return String.format(Locale.ROOT,"Value.number(java.lang.Double.longBitsToDouble(java.lang.Long.parseUnsignedLong(\"%016x\", 16)))",Double.doubleToLongBits(value));}
