  final FlowSource.Program program;final FlowSourceText.Builder output;final boolean references;final Map<String,String> functions=new HashMap<>(),classes=new HashMap<>();
  final Set<String> globals=new HashSet<>(Arrays.asList(("Value Vector Variables Intrinsics TypeSpec ArrayCell ArrayArgument FcRuntime TextFiles Turtle Problem java kotlin listOf arrayOf String Double Int Long Boolean Array List HashMap ArrayList Runtime System Math Programma fc problem finite lower shortText roundAway parseInput run").split(" ")));
  FlowSource.Scope scope;Map<String,Symbol> names;List<Symbol> symbols;Map<String,String> methods;List<Helper> helpers;int temporary;boolean inline;
  Writer(FlowSource.Program p){program=p;output=new FlowSourceText.Builder(p,"kotlin");boolean refs=false;for(FlowSource.Scope s:p.scopes)for(FlowSource.Parameter param:s.parameters)refs|=param.byReference;references=refs;int index=0;Set<String> used=globals;for(FlowSource.Scope s:p.scopes){classes.put(s.id,"FcScope"+(index++));if(s.id!=null)functions.put(s.id,unique("flow_"+identifier(s.name),used));}}
