  FlowSourceText generate(String runtime,String objectName){line("// Generato con Frociart — autore del software: mamt104",0);line("// Progetto: "+literal(program.title),0);line("// Kotlin/JVM 1.9+. kotlinc Programma.kt -include-runtime -d Programma.jar; java -jar Programma.jar",0);line("object "+objectName+" {",0);line("private var fc = FcRuntime()",1);line("@JvmStatic fun main(args: Array<String>) {",1);line("if (!fc.run({ FcScope0().run() }, true)) kotlin.system.exitProcess(1)",2);line("}",1);
   for(FlowSource.Scope s:program.scopes){if(s.id!=null){Set<String> used=new HashSet<>(globals);List<String> args=new ArrayList<>();for(FlowSource.Parameter param:s.parameters)args.add(unique(identifier(param.name),used));boolean value=s.returnType!=VOID;line("private fun "+functions.get(s.id)+"("+args.stream().map(a->a+": Value").collect(Collectors.joining(", "))+"): "+(value?"Value":"Value?")+" {",1);line("return "+(value?"fc.requireValue(":"")+classes.get(s.id)+"().run("+String.join(", ",args)+")"+(value?")":""),2);line("}",1);}scope(s);}
   line("",1);line("// --- Supporto dei tipi, dei limiti e delle operazioni di Frociart ---",1);for(String text:runtime.replace("\r\n","\n").replace('\r','\n').split("\n",-1))line(text,1);line("}",0);return output.build();
  }
  void collect(FlowSource.Expression e,Consumer<String> add){if(e==null)return;if(e.kind==FlowSource.ExpressionKind.Variable)add.accept(e.text);for(FlowSource.Expression c:e.children)collect(c,add);}
