   if(b.kind==END){if(scope.id==null)emit.accept("fc.finishFiles()");emit.accept(scope.id==null||scope.returnType==VOID?"return null":"return fc.checkType("+expression(o.value,b)+", "+scope.returnType+", "+bool(scope.returnIsArray)+")");if(!inPlace)line("}",indent,b);return;}
